SELECT COUNT(*)
FROM SHOP_BOOK
WHERE CATE_NUM = #{cateNum}

SELECT B.BOOK_NUM, B.BOOK_TITLE, B.AUTHOR, B.BOOK_PRICE, B.BOOK_STOCK, B.BOOK_INTRO, B.PUBLISH_DATE, B.CATE_NUM, C.CATE_NAME FROM SHOP_BOOK B LEFT JOIN BOOK_CATEGORY C ON B.CATE_NUM = C.CATE_NUM
(B.BOOK_TITLE LIKE CONCAT('%', #{keyword}, '%') OR B.AUTHOR LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY B.BOOK_NUM DESC LIMIT #{offset}, #{size}

mapper.update:
UPDATE SHOP_BOOK
SET BOOK_TITLE = #{bookTitle},
AUTHOR = #{author},
BOOK_PRICE = #{bookPrice},
BOOK_INTRO = #{bookIntro},
PUBLISH_DATE = #{publishDate},
CATE_NUM = #{cateNum}

	, BOOK_STOCK = #{bookStock}

WHERE BOOK_NUM = #{bookNum}

UPDATE SHOP_BOOK
SET BOOK_STOCK = BOOK_STOCK + #{quantity}
WHERE BOOK_NUM = #{bookNum}
